	json.Unmarshal(w.Body.Bytes(), &regResp)
	token := regResp["token"].(string)

	// 프로필 조회
	w = httptest.NewRecorder()
	httpReq, _ = http.NewRequest("GET", "/api/auth/profile", nil)
	httpReq.Header.Set("Authorization", "Bearer "+token)
