	TestRegisterUser(t)
	TestLoginUser(t)
	TestLoginWrongPassword(t)
	TestGetProfile(t)
	TestGetProfileUnauthorized(t)
	TestDuplicateEmail(t)

	log.Println("============================================================")
	log.Println("✅ 모든 Auth 테스트 완료!")
}

