import { ISAGenerator, Program, Assignment, BinaryOp, NumberLiteral } from './isa-generator';

/**
 * 간단한 Lexer (토큰화)
 */
class Lexer {
  private source: string;
  private position: number = 0;

  constructor(source: string) {
    this.source = source;
  }

  tokenize(): Token[] {
    const tokens: Token[] = [];

    while (this.position < this.source.length) {
      this.skipWhitespace();

      if (this.position >= this.source.length) break;

      const ch = this.source[this.position];

      // 숫자
      if (this.isDigit(ch)) {
        tokens.push(this.readNumber());
      }
      // 식별자/키워드
      else if (this.isLetter(ch)) {
        tokens.push(this.readIdentifier());
      }
      // 연산자
      else if (ch === '+') {
        tokens.push({ type: 'PLUS', value: '+' });
        this.position++;
      } else if (ch === '-') {
        tokens.push({ type: 'MINUS', value: '-' });
        this.position++;
      } else if (ch === '*') {
        tokens.push({ type: 'MUL', value: '*' });
        this.position++;
      } else if (ch === '/') {
        tokens.push({ type: 'DIV', value: '/' });
        this.position++;
      } else if (ch === '=') {
        tokens.push({ type: 'ASSIGN', value: '=' });
        this.position++;
      } else if (ch === '(') {
        tokens.push({ type: 'LPAREN', value: '(' });
        this.position++;
      } else if (ch === ')') {
        tokens.push({ type: 'RPAREN', value: ')' });
        this.position++;
      } else if (ch === '{') {
        tokens.push({ type: 'LBRACE', value: '{' });
        this.position++;
      } else if (ch === '}') {
        tokens.push({ type: 'RBRACE', value: '}' });
        this.position++;
      } else if (ch === ';') {
        tokens.push({ type: 'SEMICOLON', value: ';' });
        this.position++;
      } else {
        this.position++;
      }
    }

    tokens.push({ type: 'EOF', value: '' });
    return tokens;
  }

  private skipWhitespace(): void {
    while (
      this.position < this.source.length &&
      /\s/.test(this.source[this.position])
